-- SQL demonstrasi publik untuk pemeriksaan dosen.
-- Diimpor ke database terpisah; tidak berisi akun atau hash password.
CREATE DATABASE IF NOT EXISTS mini_digital_library_demo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mini_digital_library_demo;

CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('admin') NOT NULL DEFAULT 'admin', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE login_attempts (ip_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, window_started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, locked_until DATETIME NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_login_attempts_updated (updated_at)) ENGINE=InnoDB;
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE members (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_no VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, phone VARCHAR(30), address TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE books (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, author VARCHAR(150), publisher VARCHAR(150), publish_year SMALLINT UNSIGNED, isbn VARCHAR(30) UNIQUE, category_id INT UNSIGNED NOT NULL, stock INT UNSIGNED NOT NULL DEFAULT 0, description TEXT, cover VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_books_category FOREIGN KEY(category_id) REFERENCES categories(id) ON UPDATE CASCADE ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE borrowings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, member_id INT UNSIGNED NOT NULL, borrow_date DATE NOT NULL, due_date DATE NOT NULL, return_date DATE NULL, status ENUM('dipinjam','dikembalikan') NOT NULL DEFAULT 'dipinjam', created_by INT UNSIGNED NULL, seed_key VARCHAR(40) NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_borrow_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE RESTRICT, CONSTRAINT fk_borrow_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE borrowing_details (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, borrowing_id INT UNSIGNED NOT NULL, book_id INT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL DEFAULT 1, CONSTRAINT fk_detail_borrow FOREIGN KEY(borrowing_id) REFERENCES borrowings(id) ON DELETE CASCADE, CONSTRAINT fk_detail_book FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE RESTRICT) ENGINE=InnoDB;

